const size_t g_cn_glyph_count = sizeof(g_cn_glyphs) / sizeof(g_cn_glyphs[0]);

static const cn_glyph_t* find_glyph(uint32_t codepoint)
{
    size_t low = 0;
    size_t high = g_cn_glyph_count;

    while (low < high) {
        size_t mid = (low + high) / 2;
        uint32_t value = g_cn_glyphs[mid].codepoint;
        if (value == codepoint) {
            return &g_cn_glyphs[mid];
        }
        if (value < codepoint) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return NULL;
}

static const char* next_codepoint(const char* text, uint32_t* codepoint)
{
    const unsigned char* s = (const unsigned char*)text;

    if (s[0] < 0x80) {
        *codepoint = s[0];
        return text + 1;
    }
    if ((s[0] & 0xE0) == 0xC0 && s[1] != 0) {
        *codepoint = ((uint32_t)(s[0] & 0x1F) << 6) | (uint32_t)(s[1] & 0x3F);
        return text + 2;
    }
    if ((s[0] & 0xF0) == 0xE0 && s[1] != 0 && s[2] != 0) {
        *codepoint = ((uint32_t)(s[0] & 0x0F) << 12) |
                     ((uint32_t)(s[1] & 0x3F) << 6) |
                     (uint32_t)(s[2] & 0x3F);
        return text + 3;
    }
    if ((s[0] & 0xF8) == 0xF0 && s[1] != 0 && s[2] != 0 && s[3] != 0) {
        *codepoint = ((uint32_t)(s[0] & 0x07) << 18) |
                     ((uint32_t)(s[1] & 0x3F) << 12) |
                     ((uint32_t)(s[2] & 0x3F) << 6) |
                     (uint32_t)(s[3] & 0x3F);
        return text + 4;
    }

    *codepoint = 0xFFFD;
    return text + 1;
}

static void draw_missing(TFT_Sprite* sprite, int16_t x, int16_t y, uint16_t color)
{
    tft_sprite_draw_rect(sprite, x, y, CN_FONT_W, CN_FONT_H, color);
    tft_sprite_draw_char(sprite, x + 2, y + 2, '?', color, 2);
}

void tft_sprite_draw_utf8(TFT_Sprite* sprite, int16_t x, int16_t y,
                          const char* text, uint16_t color, uint8_t ascii_scale)
{
    if (sprite == NULL || !sprite->created || text == NULL) {
        return;
    }
    if (ascii_scale == 0) {
        ascii_scale = 1;
    }

    int16_t cx = x;
    while (*text != '\0') {
        uint32_t codepoint;
        text = next_codepoint(text, &codepoint);

        if (codepoint < 0x80) {
            int16_t glyph_height = (int16_t)(8 * ascii_scale);
            int16_t offset_y = (int16_t)((CN_FONT_H - glyph_height) / 2);
            tft_sprite_draw_char(sprite, cx, y + offset_y, (char)codepoint,
                                 color, ascii_scale);
            cx += 6 * ascii_scale;
            continue;
        }

        const cn_glyph_t* glyph = find_glyph(codepoint);
        if (glyph != NULL) {
            for (int row = 0; row < CN_FONT_H; row++) {
                for (int col = 0; col < CN_FONT_W; col++) {
                    uint8_t byte = glyph->bits[row * 2 + (col >> 3)];
                    if (byte & (0x80 >> (col & 7))) {
                        tft_sprite_draw_pixel(sprite, cx + col, y + row, color);
                    }
                }
            }
        } else {
            static bool logged_missing = false;
            if (!logged_missing) {
                ESP_LOGW(TAG, "Missing glyph U+%04X", (unsigned)codepoint);
                logged_missing = true;
            }
            draw_missing(sprite, cx, y, color);
        }
        cx += CN_FONT_W;
    }
}

int16_t tft_sprite_utf8_width(const char* text, uint8_t ascii_scale)
{
    if (text == NULL) {
        return 0;
    }
    if (ascii_scale == 0) {
        ascii_scale = 1;
    }

    int16_t width = 0;
    while (*text != '\0') {
        uint32_t codepoint;
        text = next_codepoint(text, &codepoint);
        width += (codepoint < 0x80) ? (int16_t)(6 * ascii_scale) : CN_FONT_W;
    }
    return width;
}
